PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS editions(id TEXT PRIMARY KEY, metadata_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS passages(revision_id TEXT PRIMARY KEY, edition_id TEXT NOT NULL REFERENCES editions(id), book TEXT NOT NULL, section TEXT NOT NULL, text_hash TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_spans(id TEXT PRIMARY KEY, passage_revision TEXT NOT NULL REFERENCES passages(revision_id), start_scalar INTEGER NOT NULL CHECK(start_scalar>=0), end_scalar INTEGER NOT NULL CHECK(end_scalar>start_scalar), exact_text TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS editorial_entities(id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('conclusion','expression')), current_revision TEXT NOT NULL, locked INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS revisions(id TEXT PRIMARY KEY, entity_id TEXT NOT NULL REFERENCES editorial_entities(id), kind TEXT NOT NULL, sequence INTEGER NOT NULL CHECK(sequence>0), payload_json TEXT NOT NULL, UNIQUE(entity_id,sequence));
CREATE TABLE IF NOT EXISTS lineage(target_revision TEXT NOT NULL REFERENCES revisions(id), source_revision TEXT NOT NULL REFERENCES revisions(id), PRIMARY KEY(target_revision,source_revision), CHECK(target_revision<>source_revision));
CREATE TABLE IF NOT EXISTS evidence_bundles(id TEXT PRIMARY KEY, target_revision TEXT NOT NULL REFERENCES revisions(id), mode TEXT NOT NULL CHECK(mode IN ('joint','independent')), explanation TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_links(id TEXT PRIMARY KEY, source_span TEXT NOT NULL REFERENCES source_spans(id), target_revision TEXT NOT NULL REFERENCES revisions(id), bundle_id TEXT NOT NULL REFERENCES evidence_bundles(id), relation TEXT NOT NULL CHECK(relation IN ('supports','qualifies','challenges','illustrates','depends_on','paraphrases','editorial_extrapolation')), payload_json TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS evidence_source_lookup ON evidence_links(source_span);
CREATE INDEX IF NOT EXISTS evidence_target_lookup ON evidence_links(target_revision);
CREATE TABLE IF NOT EXISTS assessments(revision_id TEXT PRIMARY KEY REFERENCES revisions(id), state TEXT NOT NULL, notes TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reviews(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL REFERENCES revisions(id), payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS concepts(id TEXT PRIMARY KEY, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS memberships(id TEXT PRIMARY KEY, concept_id TEXT NOT NULL REFERENCES concepts(id), payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS events(id TEXT PRIMARY KEY, workspace_version INTEGER NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS workspace_snapshots(version INTEGER PRIMARY KEY, payload_json TEXT NOT NULL, content_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
-- Versioned stores reserved for later stages; no mock results are inserted in these tables.
CREATE TABLE IF NOT EXISTS propositions(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL UNIQUE, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS concept_parents(child_id TEXT NOT NULL REFERENCES concepts(id), parent_id TEXT NOT NULL REFERENCES concepts(id), PRIMARY KEY(child_id,parent_id), CHECK(child_id<>parent_id));
CREATE TABLE IF NOT EXISTS embeddings(id TEXT PRIMARY KEY, input_hash TEXT NOT NULL, configuration_hash TEXT NOT NULL, entity_revision TEXT NOT NULL, model TEXT NOT NULL, dimensions INTEGER NOT NULL CHECK(dimensions=3072), vector_f32 BLOB NOT NULL, metadata_json TEXT NOT NULL, UNIQUE(input_hash,configuration_hash));
CREATE TABLE IF NOT EXISTS analysis_runs(id TEXT PRIMARY KEY, kind TEXT NOT NULL, configuration_json TEXT NOT NULL, outputs_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS jobs(id TEXT PRIMARY KEY, state TEXT NOT NULL, checkpoint_json TEXT NOT NULL, budget_json TEXT NOT NULL, cancel_requested INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ranking_assessments(id TEXT PRIMARY KEY, revision_id TEXT NOT NULL, rubric_version TEXT NOT NULL, payload_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS manuscripts(id TEXT PRIMARY KEY, version INTEGER NOT NULL, payload_json TEXT NOT NULL);
CREATE TRIGGER IF NOT EXISTS immutable_passage_update BEFORE UPDATE ON passages BEGIN SELECT RAISE(ABORT,'source passage revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_passage_delete BEFORE DELETE ON passages BEGIN SELECT RAISE(ABORT,'source passage revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_span_update BEFORE UPDATE ON source_spans BEGIN SELECT RAISE(ABORT,'source spans are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_span_delete BEFORE DELETE ON source_spans BEGIN SELECT RAISE(ABORT,'source spans are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_revision_update BEFORE UPDATE ON revisions BEGIN SELECT RAISE(ABORT,'editorial revisions are immutable'); END;
CREATE TRIGGER IF NOT EXISTS immutable_revision_delete BEFORE DELETE ON revisions BEGIN SELECT RAISE(ABORT,'editorial revisions are immutable'); END;
INSERT OR IGNORE INTO schema_migrations(version) VALUES (1);
